"""Base WAF Agent Interface and Data Models."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import List, Optional, Dict, Any

from satguardian_waf.core.payload import HTTPRequestPayload, AttackCategory, AttackDecision


@dataclass
class WAFAgentDecision:
    """Decision output generated by a WAF agent for an HTTP request."""
    agent_name: str
    decision: AttackDecision
    predicted_category: AttackCategory
    confidence: float
    latency_ms: float
    cost_usd: float
    explanation: str
    active_tokens: List[str] = field(default_factory=list)
    matched_rules: List[str] = field(default_factory=list)
    proof_latex: Optional[str] = None
    is_correct: Optional[bool] = None
    extra_metadata: Dict[str, Any] = field(default_factory=dict)

    @property
    def is_blocked(self) -> bool:
        return self.decision == AttackDecision.BLOCK


class BaseWAFAgent(ABC):
    """Abstract Base Class for WAF Agents."""

    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description

    @abstractmethod
    def inspect(self, request: HTTPRequestPayload) -> WAFAgentDecision:
        """Inspects an HTTP request and returns a deterministic or probabilistic decision."""
        pass
